@startuml

class WebPortal {
  + versionNumber : string
  + urlAddress : string
}

class Building {
  + id : string
  + name : string
  + address : string
  + yearOfConstruction : int
}

enum EnergyClass {
  A
  B
  C
  D
}

class User {
  + userName : string
  + emailAddress : string
  + password : string
}

class Administrator extends User {
  + idCardNumber : string
}

class Entry {
  + name : string
}

class TextualInformation extends Entry {}

class FloatingPointNumber extends Entry {
  + unit : string
}

class Image {
  + fileName : string
}

class Comment {
  + text : string
}

WebPortal "1" -- "*" Building : provides catalog of
Building "1" -- "1" EnergyClass
Building "1" -- "0..1" User : owned by
Building "1" *-- "*" Entry : has
Building "1" *-- "*" Image : has
User "1" -- "*" Building : creates
User "1" -- "*" Comment : writes
User "0..1" -- "*" Comment : is the subject of
WebPortal "1" -- "*" User : has

@enduml

